from throttled import Hook, Throttled, store
class BrokenBefore(Hook):
    def on_limit(self, call_next, context):
        raise RuntimeError("before")
class BrokenAfter(Hook):
    def on_limit(self, call_next, context):
        call_next()
        raise RuntimeError("after")
got = []
for hook in [BrokenBefore(), BrokenAfter()]:
    t = Throttled(key="k", quota="5/m", hooks=[hook], store=store.MemoryStore())
    got.append(log_lines("throttled.hooks", lambda: res(t.limit())))
    got.append(state(t.peek("k")))
result = got

